def run_stack_ops(operations):
    # Simulate the array-backed stack; return list of pop results (-1 when empty).
    stack = []
    results = []
    for op in operations:
        if op[0] == "push":
            stack.append(op[1])
        else:
            results.append(stack.pop() if stack else -1)
    return results

