import java.util.ArrayList;
import java.util.List;

class MyStack {
    private List<Integer> arr = new ArrayList<>();

    public void push(int x) { arr.add(x); }

    public int pop() {
        if (arr.isEmpty()) return -1;
        return arr.remove(arr.size() - 1);
    }
}
